        AncientCulture.EGYPT -> when (aspect) {
            AspectType.CONJUNCTION -> "cannot be parted from"
            AspectType.SEXTILE -> "can lean on"
            AspectType.SQUARE -> "must haul against"
            AspectType.TRINE -> "can ride the current with"
            AspectType.OPPOSITION -> "must be weighed against"
        }

        AncientCulture.GREECE -> when (aspect) {
            AspectType.CONJUNCTION -> "must climb the hill beside"
            AspectType.SEXTILE -> "can count on"
            AspectType.SQUARE -> "will quarrel with"
            AspectType.TRINE -> "can walk in step with"
            AspectType.OPPOSITION -> "will take the opposite side from"
        }

        AncientCulture.CANAAN -> when (aspect) {
            AspectType.CONJUNCTION -> "will go up to the council with"
            AspectType.SEXTILE -> "can lend a hand to"
            AspectType.SQUARE -> "will stand in the gate against"
            AspectType.TRINE -> "can work the same field as"
            AspectType.OPPOSITION -> "will bring a claim against"
        }

        AncientCulture.CARTHAGE -> when (aspect) {
            AspectType.CONJUNCTION -> "must sign under one seal with"
            AspectType.SEXTILE -> "can stand surety for"
            AspectType.SQUARE -> "will undercut"
            AspectType.TRINE -> "will tally cleanly with"
            AspectType.OPPOSITION -> "will bid against"
        }

        AncientCulture.ROME -> when (aspect) {
            AspectType.CONJUNCTION -> "must march under one standard with"
            AspectType.SEXTILE -> "can lend troops to"
            AspectType.SQUARE -> "will block the road of"
            AspectType.TRINE -> "can vote with"
            AspectType.OPPOSITION -> "will veto"
