    /** Move one's authored clause, one per body and sign, opening on "you". */
    fun placementClause(planet: Planet, sign: ZodiacSign): String = when (planet) {
        Planet.SUN -> when (sign) {
            ZodiacSign.ARIES -> "you move first and decide on the way"
            ZodiacSign.TAURUS -> "you decide slowly, and then nothing moves you"
            ZodiacSign.GEMINI -> "you find out who you are by talking it through"
            ZodiacSign.CANCER -> "you are most yourself behind your own door, feeding people"
            ZodiacSign.LEO -> "you stand where people can see you, and you warm the room"
            ZodiacSign.VIRGO -> "you know yourself by the thing you have just mended"
            ZodiacSign.LIBRA -> "you see your own shape best across a table from someone"
            ZodiacSign.SCORPIO -> "you keep the part of yourself that matters out of sight"
            ZodiacSign.SAGITTARIUS -> "you feel most like yourself on the road, headed somewhere far"
            ZodiacSign.CAPRICORN -> "you are proud of what you build and slow to show it"
            ZodiacSign.AQUARIUS -> "you stand a little apart from the crowd and watch how it works"
            ZodiacSign.PISCES -> "you take the shape of whatever room you walk into"
        }
        Planet.MOON -> when (sign) {
            ZodiacSign.ARIES -> "you feel it fast and say it before you have thought"
            ZodiacSign.TAURUS -> "you calm down with good bread and a chair you know"
            ZodiacSign.GEMINI -> "you settle a mood by talking it out with someone"
            ZodiacSign.CANCER -> "you remember every house you lived in and who was kind there"
            ZodiacSign.LEO -> "you need someone to see what you feel"
            ZodiacSign.VIRGO -> "you calm yourself by putting the house in order"
            ZodiacSign.LIBRA -> "you take your mood from the person across from you"
            ZodiacSign.SCORPIO -> "you feel everything deeply and show little of it"
            ZodiacSign.SAGITTARIUS -> "you get restless in a small room and want the open road"
            ZodiacSign.CAPRICORN -> "you get through a hard day by working through it"
            ZodiacSign.AQUARIUS -> "you go for a long walk before you say what upset you"
            ZodiacSign.PISCES -> "you soak up the mood of everyone around you"
        }
        Planet.MERCURY -> when (sign) {
            ZodiacSign.ARIES -> "you think out loud and speak first"
            ZodiacSign.TAURUS -> "you make up your mind once and keep it made up"
            ZodiacSign.GEMINI -> "you follow three conversations at once and enjoy all of them"
            ZodiacSign.CANCER -> "you remember what was said by how it made you feel"
            ZodiacSign.LEO -> "you speak to the whole room and watch its faces as you talk"
            ZodiacSign.VIRGO -> "you spot the wrong number on the page before anyone else"
            ZodiacSign.LIBRA -> "you can argue both sides and hate to choose one"
            ZodiacSign.SCORPIO -> "you listen for what people leave unsaid"
            ZodiacSign.SAGITTARIUS -> "you reach for the big rule and skip the small print"
            ZodiacSign.CAPRICORN -> "you trust an idea only once it can carry weight"
            ZodiacSign.AQUARIUS -> "you see how the whole thing is wired before you see the parts"
            ZodiacSign.PISCES -> "you think in pictures and remember how a thing felt more than what it said"
        }
        Planet.VENUS -> when (sign) {
            ZodiacSign.ARIES -> "you go after what you want before the wanting cools"
            ZodiacSign.TAURUS -> "you love slowly, and you love what lasts"
            ZodiacSign.GEMINI -> "you fall for a quick mind and a good conversation"
            ZodiacSign.CANCER -> "you love by feeding people and keeping them close"
            ZodiacSign.LEO -> "you love generously and like to be seen doing it"
            ZodiacSign.VIRGO -> "you show love by fixing whatever is broken in front of you"
            ZodiacSign.LIBRA -> "you want a partner, and you would rather keep the peace than win"
            ZodiacSign.SCORPIO -> "you love all the way or not at all"
            ZodiacSign.SAGITTARIUS -> "you want someone who shows you somewhere you have never been"
            ZodiacSign.CAPRICORN -> "you court slowly and prove your love by staying"
            ZodiacSign.AQUARIUS -> "you love a friend first and keep a little distance"
            ZodiacSign.PISCES -> "you give yourself away and forget to keep some back"
        }
        Planet.MARS -> when (sign) {
            ZodiacSign.ARIES -> "you push straight at the wall to find out where it is"
            ZodiacSign.TAURUS -> "you are slow to start and impossible to stop"
            ZodiacSign.GEMINI -> "you fight with words, and on three fronts at once"
            ZodiacSign.CANCER -> "you fight hardest when your own people are threatened"
            ZodiacSign.LEO -> "you fight best with someone watching"
            ZodiacSign.VIRGO -> "you work with care and finish the small parts properly"
