        }
        Planet.SATURN -> when (sign) {
            ZodiacSign.ARIES -> "you wait before you strike, and the strike lands"
            ZodiacSign.TAURUS -> "you build slowly, and what you build is still yours in twenty years"
            ZodiacSign.GEMINI -> "you finish one sentence before you start the next"
            ZodiacSign.CANCER -> "you carry a family duty you did not choose"
            ZodiacSign.LEO -> "you keep working when nobody is clapping"
            ZodiacSign.VIRGO -> "you keep the house in working order and know it will never be perfect"
            ZodiacSign.LIBRA -> "you say no to the person you love when no is the answer"
            ZodiacSign.SCORPIO -> "you keep a secret until the keeping costs too much"
            ZodiacSign.SAGITTARIUS -> "you wait a long time to reach the place you set out for"
            ZodiacSign.CAPRICORN -> "you take on heavy work and carry it without complaint"
            ZodiacSign.AQUARIUS -> "you keep the rule and know the one case where you would break it"
            ZodiacSign.PISCES -> "you give help all day and know when to bar the door for the night"
        }
        Planet.URANUS -> when (sign) {
            ZodiacSign.ARIES -> "you break with the old way before anyone finishes explaining it"
            ZodiacSign.TAURUS -> "you hold still for years and then change everything at once"
            ZodiacSign.GEMINI -> "you change the subject, and the whole room changes with it"
            ZodiacSign.CANCER -> "you leave the house you grew up in to build one that fits"
            ZodiacSign.LEO -> "you quit the part people cast you in, in front of all of them"
            ZodiacSign.VIRGO -> "you tear out a whole routine to fix one broken part"
            ZodiacSign.LIBRA -> "you break any bargain that asks you to keep quiet"
            ZodiacSign.SCORPIO -> "you keep quiet for months and then say everything in one night"
            ZodiacSign.SAGITTARIUS -> "you leave the creed you were raised in and go to see for yourself"
            ZodiacSign.CAPRICORN -> "you climb the ladder and then kick it away"
            ZodiacSign.AQUARIUS -> "you break old customs on principle"
            ZodiacSign.PISCES -> "you slip out of the old cage without a fight"
        }
        Planet.NEPTUNE -> when (sign) {
            ZodiacSign.ARIES -> "you charge at causes bigger than yourself"
            ZodiacSign.TAURUS -> "you make something holy of the things you can hold"
            ZodiacSign.GEMINI -> "you talk in pictures and lose the plain fact on the way"
            ZodiacSign.CANCER -> "you cry when your mother cries and laugh when your brother laughs"
            ZodiacSign.LEO -> "you play a better version of yourself until you believe it"
            ZodiacSign.VIRGO -> "you serve others until you forget to eat"
            ZodiacSign.LIBRA -> "you see your partner at their best and forgive them the rest"
            ZodiacSign.SCORPIO -> "you go all the way down with the people you love"
            ZodiacSign.SAGITTARIUS -> "you pray in any temple you pass and belong to none of them"
            ZodiacSign.CAPRICORN -> "you climb toward a summit hidden in fog"
            ZodiacSign.AQUARIUS -> "you dream of a whole city that does not exist yet"
            ZodiacSign.PISCES -> "you feel every stranger's sorrow as if it were yours"
        }
        Planet.PLUTO -> when (sign) {
            ZodiacSign.ARIES -> "you carry a scar from every fight you could not walk away from"
            ZodiacSign.TAURUS -> "you hold hardest to the things that will be taken from you"
            ZodiacSign.GEMINI -> "you dig with questions until the buried thing comes up"
            ZodiacSign.CANCER -> "you watch the house you came from torn open to its foundations"
            ZodiacSign.LEO -> "you take a public fall and are back on your feet by the next season"
            ZodiacSign.VIRGO -> "you cut away what does not work, one piece at a time"
            ZodiacSign.LIBRA -> "you choose partners who make you say what you kept quiet"
            ZodiacSign.SCORPIO -> "you go to the bottom of everything and expect others to follow"
            ZodiacSign.SAGITTARIUS -> "you watch an old belief burn and keep what comes through the fire"
            ZodiacSign.CAPRICORN -> "you see what you built stripped back to bedrock"
            ZodiacSign.AQUARIUS -> "you see the gears turning behind what others call natural"
            ZodiacSign.PISCES -> "you can lose the house and the savings and still keep your nerve"
